    cols = len(grid[0])
    visited = set()
    path = []

    def is_valid(row, col):
        return 0 <= row < rows and 0 <= col < cols and grid[row][col] == '.' and (row, col) not in visited

    def find_path(row, col):
        if (row, col) == goal:
            path.append((row, col))
            return True

        if not is_valid(row, col):
            return False

        visited.add((row, col))
        path.append((row, col))

        # Explore neighbors
        if find_path(row + 1, col):
            return True
        if find_path(row - 1, col):
            return True
        if find_path(row, col + 1):
            return True
        if find_path(row, col - 1):
            return True

        # Backtrack
        path.pop()
        return False

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]

    if find_path(start[0], start[1]):
        return path
    else:
        return []
```

